"""BRO KOREA site generator: writes every HTML page (English and Arabic), the 404 page, sitemap.xml,
robots.txt, CNAME and .nojekyll from content.py and data/. Run from anywhere: python3 generator/build.py
See generator/README.md."""
import os, sys, json, math, html, urllib.parse
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from content import CATEGORIES, BRANDS_KOREAN, BRANDS_REQUEST, MAKES_LIST, T, LEGAL_NAME_KO

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)          # the repository root: the published website
SITE = "https://brokorea.com"
EMAIL = "info@brokorea.com"
PHONE = "+82 10-3949-1286"
TEL = "+821039491286"
WA = "https://wa.me/821039491286"
REG = "201-86-30533"
# Fonts follow the company profile: Noto Sans (English), Noto Kufi Arabic Bold (Arabic headings),
# Noto Sans Arabic (Arabic text). Self-hosted WOFF2 in assets/fonts (SIL OFL 1.1); only the
# heading font of each language is preloaded.
FONT_PRELOAD = {
    "en": "assets/fonts/noto-sans-latin-700-normal.woff2",
    "ar": "assets/fonts/noto-kufi-arabic-arabic-700-normal.woff2",
}
NAVY, ACCENT = "#1F2D44", "#CD2E3A"  # logo colours: BRO Navy, Korea Red
BLUE, BLUE_SOFT = "#0F3D68", "#7FA0C2"  # profile deep blue (accents) and a lighter tint for icon details
PHOTOS = json.load(open(os.path.join(HERE, "data", "photos.json"), encoding="utf-8"))   # written by photos.py
e = html.escape
q = urllib.parse.quote


def write(rel, text):
    path = os.path.join(ROOT, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


