def icon(name, cls="i"):
    return (f'<svg class="{cls} i-{name}" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" '
            f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>')




# ---------------------------------------------------------------- helpers
def url_of(path):
    return "" if path == "index.html" else path


def href(base, path):
    if path == "index.html":
        return base or "./"
    return base + path


def wa_link(text):
    return f"{WA}?text={q(text)}"


def mailto(subject, body):
    return f"mailto:{EMAIL}?subject={q(subject)}&body={q(body)}"


def ltr(s):
    return f'<span dir="ltr">{e(s)}</span>'


def org_jsonld():
    data = {
        "@context": "https://schema.org", "@type": "Organization", "@id": SITE + "/#organization",
        "name": "BRO KOREA", "url": SITE + "/", "logo": SITE + "/images/logo.png",
        "image": SITE + "/og-image.png",
        "legalName": LEGAL_NAME_KO, "slogan": "From Korea. To the World.",
        "description": "Family-run trading company in Seoul, South Korea, connecting international customers with the Korean automotive market: vehicle trading, automotive parts, and trading & export support.",
        "taxID": REG, "email": EMAIL, "telephone": TEL,
        "address": {"@type": "PostalAddress", "addressLocality": "Seoul", "addressCountry": "KR"},
        "contactPoint": [{"@type": "ContactPoint", "contactType": "sales", "email": EMAIL, "telephone": TEL,
                          "availableLanguage": ["English", "Arabic"]}],
        "sameAs": [WA],
    }
    return '<script type="application/ld+json">' + json.dumps(data, ensure_ascii=False) + "</script>"


def layout(lang, path, title, desc, main, active=None, noindex=False, jsonld="", scripts="", root_abs=False, head_extra="", wa_float=True, form=False):
    t = T[lang]
    depth = path.count("/") + (1 if lang == "ar" else 0)
    p = "/" if root_abs else "../" * depth           # to site root
    base = p + ("ar/" if lang == "ar" else "")         # to this language's root
    other_base = p + ("" if lang == "ar" else "ar/")
    en_url = f"{SITE}/{url_of(path)}"
    ar_url = f"{SITE}/ar/{url_of(path)}"
    canon = en_url if lang == "en" else ar_url
    other_lang = "ar" if lang == "en" else "en"

    nav = "".join(
        f'<li><a href="{href(base, pth)}"{" aria-current=\"page\"" if pth == active else ""}>{e(label)}</a></li>'
        for pth, label in t["nav"])
    foot_nav = "".join(f'<li><a href="{href(base, pth)}">{e(label)}</a></li>' for pth, label in t["nav"]) + \
        f'<li><a href="{base}quote.html">{e(t["cta"])}</a></li>'

    robots = '<meta name="robots" content="noindex">' if noindex else ""
    alt = "" if noindex else (
        f'<link rel="canonical" href="{canon}">\n'
        f'<link rel="alternate" hreflang="en" href="{en_url}">\n'
        f'<link rel="alternate" hreflang="ar" href="{ar_url}">\n'
        f'<link rel="alternate" hreflang="x-default" href="{en_url}">')
    other_locale = "ar_AR" if lang == "en" else "en_US"
    wa_float_html = (f'<a class="wa-float" href="{wa_link(t["wa_text"])}" target="_blank" rel="noopener" '
                     f'aria-label="{e(t["wa_label"])}">{icon("wa")}</a>\n') if wa_float else ""

    return f"""<!doctype html>
<html lang="{lang}" dir="{t['dir']}">
<head>
<meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="{csp(form)}">
<meta name="referrer" content="strict-origin-when-cross-origin">
<meta name="viewport" content="width=device-width, initial-scale=1">
{LOGO_INTRO_HEAD}<title>{e(title)}</title>
<meta name="description" content="{e(desc)}">
{robots}{alt}
<meta property="og:type" content="website">
<meta property="og:site_name" content="BRO KOREA">
<meta property="og:title" content="{e(title)}">
<meta property="og:description" content="{e(desc)}">
<meta property="og:url" content="{canon}">
<meta property="og:image" content="{SITE}/og-image.png">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:locale" content="{t['locale']}">
<meta property="og:locale:alternate" content="{other_locale}">
<meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#ffffff">
<link rel="icon" href="{p}favicon.ico" sizes="any">
<link rel="icon" href="{p}favicon.svg" type="image/svg+xml">
<link rel="apple-touch-icon" href="{p}apple-touch-icon.png">
<link rel="manifest" href="{p}site.webmanifest">
<link rel="preload" href="{p}{FONT_PRELOAD[lang]}" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="{p}assets/css/style.css">
{head_extra}{jsonld}
</head>
<body>
<a class="skip" href="#main">{e(t['skip'])}</a>
<header class="site-header">
  <div class="wrap header-in">
    <a class="brand" href="{href(base, 'index.html')}">{logo_anim_svg(header=True)}</a>
    <nav id="site-nav" class="nav" aria-label="Main">
      <ul>{nav}</ul>
    </nav>
    <div class="header-actions">
      <a class="lang-switch" href="{href(other_base, path)}" hreflang="{other_lang}" lang="{other_lang}">{e(t['other_label'])}</a>
      <a class="btn btn-primary btn-sm" href="{base}quote.html"><span class="hide-xs">{e(t['cta'])}</span><span class="show-xs">{e(t['cta_short'])}</span></a>
      <button class="menu-btn" type="button" aria-expanded="false" aria-controls="site-nav" data-label-open="{e(t['menu_open'])}" data-label-close="{e(t['menu_close'])}"><span class="bars" aria-hidden="true"></span><span class="sr-only">{e(t['menu_open'])}</span></button>
    </div>
  </div>
</header>
<main id="main">
{main}
</main>
<footer class="site-footer">
  <div class="wrap footer-grid">
    <div>
      <p class="foot-brand"><img src="{p}images/logo-white.svg" width="123" height="80" alt="BRO KOREA" loading="lazy"></p>
      <p>{e(t['tagline'])}</p>
      <p>{e(t['reg'])}: {ltr(REG)}<br><span lang="ko">{LEGAL_NAME_KO}</span></p>
    </div>
    <div>
      <p class="foot-h">{e(t['foot_contact'])}</p>
      <ul class="foot-contact">
        <li>{icon('mail')}<a href="mailto:{EMAIL}">{EMAIL}</a></li>
        <li>{icon('phone')}<a href="tel:{TEL}">{ltr(PHONE)}</a></li>
        <li>{icon('wa')}<a href="{wa_link(t['wa_text'])}" target="_blank" rel="noopener">{e(t['wa_l'])}: {ltr(PHONE)}</a></li>
        <li>{icon('pin')}<span>{e(t['seoul'])}</span></li>
      </ul>
    </div>
    <div>
      <p class="foot-h">{e(t['foot_pages'])}</p>
      <ul class="foot-links">{foot_nav}</ul>
    </div>
  </div>
  <div class="wrap foot-bottom">© <span data-year>2026</span> BRO KOREA. {e(t['rights'])}</div>
</footer>
{wa_float_html}{scripts}<script src="{p}assets/js/logo-anim.js" defer></script>
<script src="{p}assets/js/main.js" defer></script>
</body>
</html>
"""


def ctx(lang, path):
    depth = path.count("/") + (1 if lang == "ar" else 0)
    p = "../" * depth
    return p, p + ("ar/" if lang == "ar" else "")


