# ---------------------------------------------------------------- sitemap
def sitemap():
    paths = ["index.html", "catalog.html"] + [f"catalog/{c['slug']}.html" for c in CATEGORIES] + \
        ["brands.html", "how-it-works.html", "quote.html", "about.html"]
    out = ['<?xml version="1.0" encoding="UTF-8"?>',
           '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">']
    for pth in paths:
        en = f"{SITE}/{url_of(pth)}"; ar = f"{SITE}/ar/{url_of(pth)}"
        for loc in (en, ar):
            out.append(f"  <url>\n    <loc>{loc}</loc>\n    <lastmod>2026-10-21</lastmod>\n"
                       f'    <xhtml:link rel="alternate" hreflang="en" href="{en}"/>\n'
                       f'    <xhtml:link rel="alternate" hreflang="ar" href="{ar}"/>\n'
                       f'    <xhtml:link rel="alternate" hreflang="x-default" href="{en}"/>\n  </url>')
    out.append("</urlset>\n")
    return "\n".join(out)


def main():
    for lang in ("en", "ar"):
        pre = "ar/" if lang == "ar" else ""
        write(pre + "index.html", home(lang))
        write(pre + "catalog.html", catalog(lang))
        for c in CATEGORIES:
            write(pre + f"catalog/{c['slug']}.html", category(lang, c))
        write(pre + "brands.html", brands(lang))
        write(pre + "how-it-works.html", how(lang))
        write(pre + "quote.html", quote(lang))
        write(pre + "about.html", about(lang))
        write(pre + "thank-you.html", thanks(lang))
    write("404.html", not_found())
    # (the old line-drawing SVGs are retired: every category now has a product image)
    write("sitemap.xml", sitemap())
    write("robots.txt", f"User-agent: *\nAllow: /\n\nSitemap: {SITE}/sitemap.xml\n")
    write("CNAME", "brokorea.com\n")
    write(".nojekyll", "")


if __name__ == "__main__":
    main()
